export class AttachmentError extends Error {
  constructor(
    readonly code:
      | "ATTACHMENT_REJECTED"
      | "ATTACHMENT_TOO_LARGE"
      | "TOO_MANY_ATTACHMENTS"
      | "ATTACHMENT_UNAVAILABLE"
      | "ATTACHMENT_STORAGE_FAILED",
    readonly reason?:
      | "download_metadata"
      | "download_body"
      | "download_partial"
      | "download_timeout",
  ) {
    super(code);
    this.name = "AttachmentError";
  }
}

// Keys are generated by the store. Remote filenames never participate in path resolution.
export interface AttachmentStore {
  put(
    bytes: AsyncIterable<Uint8Array>,
    maxBytes: number,
  ): Promise<{ key: string; sizeBytes: number; release: () => void }>;
  read(key: string): AsyncIterable<Uint8Array>;
  remove(key: string): Promise<void>;
  sweep(retained: () => ReadonlySet<string>, olderThan: number): Promise<void>;
}
